//
//  ToolNeedRouter.swift
//  M1K3Chat
//
//  Does this chat turn need a tool at all? Measured 2026-09-26 (live A/B, Mini,
//  22 chat fixtures, app quit): the same chat turn took a median 51.5 s with
//  the tool palette and 13.4 s without, and scored better without (13 → 15/22;
//  with tools Mini disowned "the capital of Australia"). So a turn the router
//  reads as plain chat skips the palette.
//
//  The router is a logistic layer (ToolNeedRouterWeights, generated by
//  tools/router/train_tool_router.py) over Apple's built-in English sentence
//  embedding: nothing downloaded, ~5 ms. The spike (scratch/laya-spike) tried
//  Laya, an MLX decision encoder, first: zero-shot it could not see web asks;
//  trained on the same labels, Apple's embedding matched it without a ~1 GB
//  model. On the eval fixtures, never trained on: 42/42 tool asks kept, 28/74
//  no-tool turns freed.
//
//  It fails OPEN. No vector (another language, no embedding asset), a vector of
//  the wrong size, or a non-finite score keeps the tools: hiding a tool the
//  turn needed is a wrong answer, keeping one it didn't is only slower. On a
//  short turn only a CONFIDENT non-English guess counts (the guess is noise under
//  ~24 characters); a long turn with no language signal at all abstains.
//
//  Signed: Kev + claude-opus-5-5, 2026-09-26, Confidence 0.75 (pure and pinned;
//  the weights come from synthetic data until a shadow log grows real labels,
//  and the live gain is re-measured once the chat route is wired). Prior: Unknown.
//  Review: Kev + claude-opus-5-5, 2026-09-26 — challenger review: the strict
//  dominant-language gate failed "hi" (Catalan), "lol" (Dutch) and "ok cool" (Polish)
//  open to the palette. Short turns now skip the guess. Confidence 0.8.
//  Review: same day, PR #414 review — skipping the guess also scored short NON-English
//  tool asks with the English model. A short turn now abstains on a confident non-English
//  guess (≥ 0.9); the noisy English misreads are low-confidence. Confidence 0.8.
//  Review: same day, PR #414 review (fe9a04ac) — that fold read a long turn with NO language
//  signal (the recognizer's nil: digits, emoji) as English; it abstains again. Confidence 0.85.
//  Review: Kev + claude-opus-5-5, 2026-10-17 — `pointsBackInChat` (#622): a turn about what was said in this
//  chat is the replay's to answer, not a tool's; past sessions and the user's stores are left to the gate.
//  Pinned so no tool-use fixture trips it. Confidence 0.75 (word cues; the rig replay is owed).
//  Review: Kev + claude-opus-5.5, 2026-10-17 — `PlainTurnStream` tells an answer from reasoning
//  alone (`hasAnswer`, `thoughtWithoutAnswering`): a think-to-the-cap stream had read as answered.
//  Confidence 0.85.
//  Review: Kev + claude-opus-5-5, 2026-10-18 — `thinkingPastBudget`: open reasoning over the thinking cap;
//  closed reasoning never counts, so an answer on its way is never cut. Confidence 0.85.
//  Review: Kev + claude-opus-5-5, 2026-10-19 — the 10-17 entry's Confidence line back under it (comment only).
//  Review: Kev + claude-opus-5.5, 2026-10-26 — `PlainTurnRoute.staysLocal` (#713): the search head's reading of the
//  turn, asked only when a pick reads the web; nil (the default) changes nothing. Confidence 0.85.
//  Review: Kev + claude-opus-5.5, 2026-11-02 — `NLSentenceEmbedder` no longer keeps a miss. On Kev's
//  iPhone the sentence asset wasn't ready at launch and was a moment later (a launch-arg probe, no asset
//  request needed); the load-once nil made every phone turn `p=none`, so the picker sent small talk to
//  datetime and Mini opened every reply with the clock. Confidence 0.85 (proven on one phone, iOS 27.2).
//  Review: Kev + claude-opus-5.5, 2026-11-02 — `contentFreeReply` (a whole-turn whitelist: thanks and bare praise
//  close, a go phrase beats a no, a "later" beats a go) and `offerText` (the previous reply's last two sentences, a
//  links-only sources tail cut, for the gate to read on a yes; no cue lists): on the phone "Yes. Please." after a
//  story offer scored tools at 0.799 and the picker invented a New York weather search. Confidence 0.7 (pinned; the
//  gate reads request-shaped offers as tools, so creative offers reach the picker as text; device check owed).
//

import Foundation
import M1K3Inference
import NaturalLanguage

public enum ToolNeedRouter {
    public enum Verdict: Sendable, Equatable {
        /// Offer the tool palette as today.
        case tools
        /// Plain chat: answer without the palette.
        case chat
    }

    /// P(needs a tool) for one sentence vector; nil when it can't be scored.
    public static func probability(_ vector: [Double]) -> Double? {
        let weights = ToolNeedRouterWeights.weights
        guard vector.count == weights.count else { return nil }
        let norm = vector.reduce(0) { $0 + $1 * $1 }.squareRoot()
        guard norm > 0, norm.isFinite else { return nil }
        var z = ToolNeedRouterWeights.bias
        for (value, weight) in zip(vector, weights) {
            z += value / norm * weight
        }
        let p = 1 / (1 + exp(-z))
        return p.isFinite ? p : nil
    }

    public static func verdict(probability: Double?) -> Verdict {
        guard let probability, probability.isFinite else { return .tools }
        return probability >= ToolNeedRouterWeights.threshold ? .tools : .chat
    }

    public static func verdict(for question: String, embed: (String) -> [Double]?) -> Verdict {
        decide(for: question, embed: embed).verdict
    }

    /// The verdict with the score behind it (nil when it couldn't be scored), so
    /// a caller can log what the router saw: those lines are future labels.
    public struct Decision: Sendable, Equatable {
        public let verdict: Verdict
        public let probability: Double?

        public init(verdict: Verdict, probability: Double?) {
            self.verdict = verdict
            self.probability = probability
        }
    }

    public static func decide(for question: String, embed: (String) -> [Double]?) -> Decision {
        let p = embed(question).flatMap(probability)
        return Decision(verdict: verdict(probability: p), probability: p)
    }

    /// Does the turn ask about what was said in THIS conversation ("what did you say about names
    /// earlier?", "who did I say is coming?")? The responder answers such a turn from the replay
    /// when the chat has history (#622): the gate scores it 0.4–0.7, a sentence vector can't tell
    /// "earlier in this chat" from "earlier, another day", and `recent_activity` then put another
    /// chat's facts in the answer. A turn that names a past session (yesterday, a weekday, last
    /// week) or one of the user's stores (notes, calendar, a recording) is left to the gate.
    ///
    /// Acting on what was said ("Open the link you mentioned", "Play the song you recommended")
    /// keeps its tools (`actionCues`), and the responder only overrides a verdict below
    /// `pointsBackCeiling`: the gate's grey zone, where look-backs scored 0.4–0.7.
    public static func pointsBackInChat(_ question: String) -> Bool {
        // "just now" and "earlier today" point back in THIS chat; they aren't the now/today of a fresh ask.
        let text = question.lowercased()
            .replacingOccurrences(of: "just now", with: "just")
            .replacingOccurrences(of: "earlier today", with: "earlier")
        return ToolGroupRouter.mentions(text, any: saidCues)
            && !ToolGroupRouter.mentions(text, any: pastSessionCues + storeCues + nowCues + actionCues)
    }

    /// Above this the gate is sure a tool is wanted (a past-session look-back scores ~0.87).
    public static let pointsBackCeiling = 0.8

    /// What a content-free reply says: yes, no, or only a closing ("thanks", "great").
    public enum ReplyKind: Sendable, Equatable {
        case affirmative, declining, neutral
    }

    /// A turn with nothing in it for a tool: every word is a yes, a no, a thanks, praise or a filler
    /// ("Yes. Please.", "No thanks", "Cheers Mike", 👍). A WHOLE-TURN whitelist: any other word
    /// ("yes, Cork", "do it again", "more") is nil and keeps today's path, so a miss loses
    /// nothing. 2026-11-02 on Kev's iPhone: after a story offer, "Yes. Please." scored tools at
    /// 0.799 and Apple's picker, which sees only this message, invented a New York weather
    /// search. "again", "more", "next" and "another" stay off the list: they want a fresh read.
    ///
    /// Thanks and bare praise close ("Great, thanks" is neutral); only an acceptance word beside
    /// them makes a yes ("Great, yes please"). A no is a no unless the turn carries a go phrase
    /// ("No, go ahead", "Ah no, go on"); a deferral ("later", "not now") wins over any go phrase
    /// ("do it later"): not now means not now.
    public static func contentFreeReply(_ text: String) -> ReplyKind? {
        let folded = text.folding(options: [.diacriticInsensitive, .caseInsensitive], locale: nil)
        let words = ToolGroupRouter.words(folded).map(String.init)
        guard !words.isEmpty else {
            let scalars = text.unicodeScalars.map(\.value)
            if scalars.contains(where: affirmativeEmoji.contains) { return .affirmative }
            if scalars.contains(where: decliningEmoji.contains) { return .declining }
            return nil
        }
        var tags: Set<ReplyTag> = []
        var goes = false
        var index = 0
        while index < words.count {
            // Longest phrase first: "no worries" is a thanks, "no" alone a decline.
            guard let match = replyPhrases.first(where: { entry in
                let end = index + entry.phrase.count
                return end <= words.count && Array(words[index ..< end]) == entry.phrase
            }) else { return nil }
            tags.insert(match.tag)
            if goPhrases.contains(match.phrase) { goes = true }
            index += match.phrase.count
        }
        if tags.contains(.deferring) { return .declining }
        if tags.contains(.declining) { return goes ? .affirmative : .declining }
        if tags.contains(.accepting) { return .affirmative }
        return .neutral
    }

    /// What one phrase of a reply carries. A closing is a thanks or bare praise; a filler only rides along.
    enum ReplyTag: Hashable {
        case accepting, declining, deferring, closing, filler
    }

    /// 👍 🙌 👌 🙏 ✅ say yes, 👎 says no; any other emoji alone is not read.
    static let affirmativeEmoji: Set<UInt32> = [0x1F44D, 0x1F64C, 0x1F44C, 0x1F64F, 0x2705]
    static let decliningEmoji: Set<UInt32> = [0x1F44E]

    /// The yeses that ask for the thing to be done: beside a no ("No, go ahead") they win.
    static let goPhrases: Set<[String]> = Set([
        "go", "go on", "go ahead", "go for it", "do it", "do that", "do this", "do so", "please do", "carry on",
        "keep going", "continue", "let s do it", "lets do it", "let s go", "tell me",
    ].map { $0.split(separator: " ").map(String.init) })

    /// Every phrase a content-free reply may be made of, longest first. Words are letters only,
    /// so "I'd" and "I\u{2019}d" are both "i d"; accents are folded ("sí" is "si").
    static let replyPhrases: [(phrase: [String], tag: ReplyTag)] = {
        let accepting = [
            "yes", "yeah", "yea", "yep", "yup", "aye", "sure", "sure thing", "please", "pls", "plz", "ok", "okay",
            "k", "alright", "go", "go on", "go ahead", "go for it", "do it", "do that", "do this", "do so",
            "please do", "let s do it", "lets do it", "let s go", "why not", "absolutely", "definitely", "course",
            "of course", "mhm", "mm hmm", "uh huh", "sounds good", "sounds great", "continue", "carry on",
            "keep going", "deal", "love it", "love that", "i d love that", "i would", "tell me",
            // Accent-folded: oui, sí/si, ja, sim, tak, bitte, por favor, s'il vous plaît, d'accord, vale, claro.
            "oui", "si", "ja", "sim", "tak", "bitte", "por favor", "s il vous plait", "d accord", "vale", "claro",
            // Irish "'Sea" (is ea, "it is"), a yes on its own; "the sea" has "the" and stays nil.
            "sea",
        ]
        let declining = [
            "no", "nope", "nah", "not really", "no thanks", "no thank you", "non", "nein", "nee", "nao", "nie",
        ]
        let deferring = ["later", "maybe later", "not now", "not yet"]
        let closing = [
            "thanks", "thank you", "thx", "cheers", "ta", "no worries", "no problem", "fair enough", "merci", "danke",
            "gracias", "grazie", "obrigado", "obrigada", "dziekuje", "go raibh maith agat", "go raibh maith agaibh",
            "go raibh mile maith agat",
            // Bare praise: a closing, not a yes ("Great, thanks" after an offer).
            "great", "perfect", "cool", "lovely", "grand", "nice", "brilliant", "fine", "excellent", "awesome", "good",
        ]
        let fillers = [
            "that", "this", "it", "i", "d", "m", "s", "ll", "would", "be", "love", "do", "so", "then", "very",
            "much", "really", "a", "lot", "many", "sounds", "mike", "m1k3", "oh", "ah", "well", "just", "maybe",
            "beaucoup", "schon", "muchas", "mille", "tres", "bien",
        ]
        let all = accepting.map { ($0, ReplyTag.accepting) } + declining.map { ($0, ReplyTag.declining) }
            + deferring.map { ($0, ReplyTag.deferring) } + closing.map { ($0, ReplyTag.closing) }
            + fillers.map { ($0, ReplyTag.filler) }
        return all.map { (phrase: $0.0.split(separator: " ").map(String.init), tag: $0.1) }
            .sorted { $0.phrase.count > $1.phrase.count }
    }()

    /// What M1K3 just offered, for the gate to read when the user says yes to it: the previous
    /// reply's last two sentences with letters in them (StyleAskFence's split), joined on one line,
    /// double quotes stripped, at most `offerTextLimit` characters (the end kept: the offer is
    /// last). Reasoning and a FOLLOWUPS trailer are cut first, and a trailing sources block only
    /// when it is a list of links ("Web sources:" then lines of "•", "-", "*" or a URL): a prose
    /// line that names sources is the reply. nil when the history doesn't end on M1K3's turn or
    /// nothing there has letters. No cue lists (round 2's held 44% on a held-out set): the trained
    /// gate decides whether the offer wants a tool, and the picker reads it in place of "yes".
    public static func offerText(in history: [ChatTurn]) -> String? {
        guard let last = history.last, last.role == .assistant else { return nil }
        let text = withoutSourcesTail(FollowUpSplit.split(ReasoningSplit.split(last.text).answer).answer)
        let sentences = StyleAskFence.segments(text).filter { $0.contains(where: \.isLetter) }
        let quotes: Set<Character> = ["\"", "\u{201C}", "\u{201D}", "\u{201E}", "\u{00AB}", "\u{00BB}"]
        let joined = sentences.suffix(2).joined(separator: " ").filter { !quotes.contains($0) }
            .split(whereSeparator: \.isWhitespace).joined(separator: " ")
        guard !joined.isEmpty else { return nil }
        guard joined.count > offerTextLimit else { return joined }
        let start = joined.index(joined.endIndex, offsetBy: -offerTextLimit)
        var capped = joined[start...]
        // A cut word at the front is noise for the gate: start at the next whole word.
        if !joined[joined.index(before: start)].isWhitespace, let space = capped.firstIndex(of: " ") {
            capped = capped[capped.index(after: space)...]
        }
        return String(capped)
    }

    static let offerTextLimit = 300

    /// The reply without its trailing sources blocks: each a "<Something> sources:" line followed
    /// only by link lines. Anything else after the header (an offer, prose) keeps the block.
    static func withoutSourcesTail(_ text: String) -> String {
        var lines = text.components(separatedBy: .newlines)
        while true {
            while let last = lines.last, last.trimmingCharacters(in: .whitespaces).isEmpty {
                lines.removeLast()
            }
            guard let header = lines.lastIndex(where: { $0.wholeMatch(of: sourcesHeader) != nil }) else { break }
            let rest = lines[(header + 1)...].map { $0.trimmingCharacters(in: .whitespaces) }.filter { !$0.isEmpty }
            let links = rest.allSatisfy { line in
                ["•", "-", "*"].contains { line.hasPrefix($0) } || line.contains("http")
            }
            guard !rest.isEmpty, links else { break }
            lines.removeSubrange(header...)
        }
        return lines.joined(separator: "\n")
    }

    /// "Web sources:", "Wikipedia sources:", "Sources:" alone on its line.
    nonisolated(unsafe) static let sourcesHeader = /[ \t]*(?:[A-Za-z][A-Za-z ]* )?[Ss]ources:[ \t]*/

    /// "<who> [just] <said>" in the past tense, or "<did|do> <who> <say>": a present form alone is
    /// an everyday request ("Can you tell me the weather?", "Can you recommend…"), challenger
    /// 2026-10-17, so it counts only after did/do ("did you say", "do you mean").
    static let saidCues: [String] = {
        let who = ["you", "i", "we"]
        let past = ["said", "mentioned", "suggested", "told", "talked", "discussed", "recommended", "picked", "listed"]
        let present = ["say", "mention", "suggest", "tell", "talk", "discuss", "recommend", "mean", "pick", "list"]
        // "you meant" asks about M1K3's words; "I meant" corrects the user's own last turn (a fresh ask).
        let pastCues = who.flatMap { who in past.flatMap { ["\(who) \($0)", "\(who) just \($0)"] } }
            + ["you meant", "you just meant"]
        // "did" with any verb; "do" only where it asks about words ("What laptop do you recommend?" is a fresh ask).
        let didCues = who.flatMap { who in present.map { "did \(who) \($0)" } }
        let wordVerbs = ["say", "mean", "mention", "tell", "talk", "discuss"]
        let doCues = who.flatMap { who in wordVerbs.map { "do \(who) \($0)" } }
        return pastCues + didCues + doCues
    }()

    /// The turn wants something current, or complains about an action ("I told you to set a
    /// timer"): not a look-back, whatever verb it uses.
    static let nowCues = ToolDispatch.nowCues + [
        "now", "tomorrow", "told you to", "asked you to",
        "weather", "forecast", "rain", "price", "prices", "score", "scores", "news", "traffic",
    ]

    /// Acting on what was said needs the tool that acts (code review, 2026-10-17).
    static let actionCues = [
        "remind", "set", "timer", "alarm", "schedule", "book", "send", "text", "message", "call", "play",
        "open", "launch", "run", "save", "add", "create", "write", "copy",
        "link", "url", "site", "website", "page", "browser",
    ]

    static let pastSessionCues = [
        "yesterday", "last week", "last night", "last time", "last month", "last weekend", "last session",
        "the other day", "days ago", "weeks ago", "months ago", "this morning", "previous", "another chat",
        "other chat", "our chat", "our conversation", "that conversation", "session",
        "monday", "tuesday", "wednesday", "thursday", "friday", "saturday", "sunday",
    ]

    static let storeCues = [
        "note", "notes", "calendar", "reminder", "reminders", "todo", "todos", "email", "emails", "document",
        "documents", "file", "files", "recording", "recorded", "meeting", "search", "look up", "web", "online",
    ]
}

/// How a turn the router reads as plain chat is answered: `decide` is the
/// router, `instructions` the persona for the plain generation (nil keeps the
/// provider's own, which on Mini is the prewarmed one).
public struct PlainTurnRoute: Sendable {
    public let decide: @Sendable (String) -> ToolNeedRouter.Decision
    public let instructions: String?
    /// On a turn that needs a tool: names ONE tool from the menu (question, menu),
    /// which the app then runs itself (ToolDispatch). nil, or a nil pick, keeps the
    /// agent turn.
    public let pick: (@Sendable (String, String) async -> ToolPick?)?
    /// The search head (#713, `toolSearchHead`): does this turn need the web? Asked only when the
    /// pick reads the web; `.local` takes the web reads back out (`ToolDispatch.searchCorrected`).
    /// nil keeps every pick as the picker named it.
    public let staysLocal: (@Sendable (String) -> SearchRouter.Decision)?

    public init(
        decide: @escaping @Sendable (String) -> ToolNeedRouter.Decision,
        instructions: String?,
        pick: (@Sendable (String, String) async -> ToolPick?)? = nil,
        staysLocal: (@Sendable (String) -> SearchRouter.Decision)? = nil
    ) {
        self.decide = decide
        self.instructions = instructions
        self.pick = pick
        self.staysLocal = staysLocal
    }
}

/// The plain turn replays history as `USER:` / `M1K3:` lines, and a small model
/// may answer in that transcript voice, so the label is cut from the answer.
/// Providers stream either cumulative snapshots (AFM) or deltas (MLX): `ingest`
/// folds either into the whole answer so far, and yields the cleaned WHOLE text
/// each time it grows, so every yield extends the last and a held first piece
/// ("M", which might have become the label) is never lost (code review).
public struct PlainTurnStream {
    static let label = "M1K3:"
    private var raw = ""
    private var sent = ""

    public init() {}

    /// One provider chunk in; the cleaned answer so far when it grew, else nil.
    public mutating func ingest(_ chunk: String) -> String? {
        raw = StreamFold.fold(current: raw, chunk: chunk)
        guard let clean = Self.clean(raw), clean.count > sent.count, clean.hasPrefix(sent) else { return nil }
        sent = clean
        return clean
    }

    /// The stream holds answer text, not only reasoning. A think-phase stream cut at the
    /// token cap before `</think>` is all reasoning: no answer, however much it yielded.
    public var hasAnswer: Bool {
        !ReasoningSplit.split(sent).answer.isEmpty
    }

    /// Reasoning came back and no answer did: the model thought to the cap (2026-10-17,
    /// live on Always-think: Lil argued with the FOLLOWUPS rule until it ran out), or closed
    /// its reasoning and stopped. Needs an open or close tag in the stream: the MLX provider
    /// yields the opener a pre-opened template swallows (`thinkPrefixNeeded`), so a brain
    /// that streams bare reasoning with neither would still read as answered.
    public var thoughtWithoutAnswering: Bool {
        let split = ReasoningSplit.split(sent)
        return split.answer.isEmpty && !(split.reasoning ?? "").isEmpty
    }

    /// The snapshot so far with its reasoning closed, so an answer generated after it
    /// extends the last yield (the consumer folds snapshots) and the reasoning stays shown.
    /// Reasoning that already closed gets no second close: it would sit in the bubble as text.
    var closedReasoning: String {
        sent + (reasoningIsClosed ? "\n\n" : "\n</think>\n\n")
    }

    /// Reasoning still open, and longer than `budget` characters: the think phase has run past
    /// the cap (`ThinkingPolicy.thinkingBudgetCharacters`). Closed reasoning never counts.
    public func thinkingPastBudget(_ budget: Int) -> Bool {
        guard !reasoningIsClosed, let reasoning = ReasoningSplit.split(sent).reasoning else { return false }
        return reasoning.count > budget
    }

    /// The last close tag comes after the last open tag (or there is a close and no open).
    private var reasoningIsClosed: Bool {
        func last(_ tags: [String]) -> String.Index? {
            tags.compactMap { sent.range(of: $0, options: .backwards)?.lowerBound }.max()
        }
        let close = last(ReasoningSplit.closeTags)
        return close.map { close in last(ReasoningSplit.openTags).map { close > $0 } ?? true } ?? false
    }

    // The label cut from a WHOLE answer so far; nil while it could still become the label.

    public static func clean(_ snapshot: String) -> String? {
        let text = snapshot.drop(while: \.isWhitespace)
        if label.hasPrefix(text) { return nil }
        guard text.hasPrefix(label) else { return String(text) }
        let rest = text.dropFirst(label.count).drop(while: \.isWhitespace)
        return rest.isEmpty ? nil : String(rest)
    }
}

/// Apple's English sentence embedding, abstaining on text that isn't English
/// (the weights only know that space). `NLEmbedding` is read-only, so once found it is kept;
/// a miss is NOT kept. On Kev's iPhone (2026-11-02) the asset wasn't ready at launch and was a
/// moment later, and the old load-once property held that first nil for the whole process:
/// every turn scored `p=none` and failed open to the picker, which sent "what's up?" to datetime.
public final class NLSentenceEmbedder: @unchecked Sendable {
    public typealias Vectoriser = @Sendable (String) -> [Double]?

    private let resolve: @Sendable () -> Vectoriser?
    private var vectorise: Vectoriser?
    private let lock = NSLock()

    public convenience init() {
        self.init {
            guard let embedding = NLEmbedding.sentenceEmbedding(for: .english) else { return nil }
            // Read-only and only ever called under `lock`, so the capture is safe.
            nonisolated(unsafe) let held = embedding
            return { held.vector(for: $0) }
        }
    }

    /// `resolve` is asked on each turn until it returns an embedding, then never again.
    init(resolve: @escaping @Sendable () -> Vectoriser?) {
        self.resolve = resolve
    }

    public func vector(_ text: String) -> [Double]? {
        guard Self.readsAsEnglish(text) else { return nil }
        // NLEmbedding documents no thread-safety guarantee; turns are rare, so serialise.
        return lock.withLock {
            if vectorise == nil { vectorise = resolve() }
            return vectorise?(text)
        }
    }

    /// Abstain only when English is clearly unlikely. On a short turn the guess is
    /// noise unless it is confident: "hi" reads as Catalan at 0.80 and "lol" as Dutch
    /// at 0.24, while "busca mi correo" is Spanish at 0.97 (measured 2026-09-26). So a
    /// short turn abstains only on a confident non-English guess; a longer one on
    /// any non-English guess. Either way, English at 0.2 or more keeps the vector.
    static func readsAsEnglish(_ text: String) -> Bool {
        let recognizer = NLLanguageRecognizer()
        recognizer.processString(text)
        // No signal at all (digits, emoji): a short turn is read, a long one abstains.
        guard let top = recognizer.dominantLanguage else { return text.count < shortTurnLength }
        if top == .english { return true }
        let hypotheses = recognizer.languageHypotheses(withMaximum: 3)
        if (hypotheses[.english] ?? 0) >= 0.2 { return true }
        return text.count < shortTurnLength && (hypotheses[top] ?? 0) < confidentGuess
    }

    static let shortTurnLength = 24
    static let confidentGuess = 0.9
}
